BEGIN READ ONLY;
SELECT 'business_tables',count(*) FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name <> 'flyway_schema_history';
SELECT 'null_order_warehouse',count(*) FROM orders WHERE warehouse_id IS NULL;
SELECT 'order_header_vs_lines',count(*) FROM orders o WHERE o.subtotal IS DISTINCT FROM (SELECT coalesce(sum(i.unit_price*i.quantity),0) FROM order_items i WHERE i.order_id=o.order_id) OR o.discount_amount IS DISTINCT FROM (SELECT coalesce(sum(i.discount_amount*i.quantity),0) FROM order_items i WHERE i.order_id=o.order_id);
SELECT 'invoice_vs_order_total',count(*) FROM invoices v JOIN orders o USING(order_id) WHERE v.total_amount<>o.total_amount;
SELECT 'return_wrong_owner',count(*) FROM return_requests r JOIN orders o USING(order_id) WHERE r.customer_id<>o.customer_id;
SELECT 'return_wrong_order_line',count(*) FROM return_items i JOIN return_requests r USING(return_id) JOIN order_items oi USING(order_item_id) WHERE oi.order_id<>r.order_id OR i.serial_id IS DISTINCT FROM oi.serial_id;
SELECT 'warranty_wrong_owner_or_device',count(*) FROM warranties w JOIN order_items i USING(order_item_id) JOIN orders o USING(order_id) WHERE w.customer_id<>o.customer_id OR w.serial_id IS DISTINCT FROM i.serial_id;
SELECT 'ticket_wrong_owner_or_device',count(*) FROM warranty_tickets t JOIN warranties w USING(warranty_id) WHERE t.customer_id<>w.customer_id OR t.serial_id<>w.serial_id;
SELECT 'review_wrong_owner_or_product',count(*) FROM reviews r JOIN order_items i USING(order_item_id) JOIN orders o USING(order_id) JOIN product_variants v USING(variant_id) WHERE r.customer_id<>o.customer_id OR r.product_id<>v.product_id;
SELECT 'chat_wrong_session_owner',count(*) FROM chat_history h JOIN chat_sessions s USING(session_id) WHERE h.customer_id<>s.customer_id;
SELECT 'feedback_wrong_message_owner',count(*) FROM message_feedback f JOIN chat_history h USING(history_id) WHERE f.customer_id<>h.customer_id;
SELECT 'serial_wrong_variant_or_warehouse',count(*) FROM order_items i JOIN serial_numbers s USING(serial_id) JOIN orders o USING(order_id) WHERE i.variant_id<>s.variant_id OR o.warehouse_id IS DISTINCT FROM s.warehouse_id;
SELECT 'available_serial_still_attached_to_history',count(*) FROM serial_numbers s WHERE s.status='AVAILABLE' AND EXISTS(SELECT 1 FROM order_items i WHERE i.serial_id=s.serial_id);
SELECT 'tracked_inventory_vs_serial_count',count(*) FROM inventory i JOIN product_variants v USING(variant_id) WHERE v.tracking_type<>'NONE' AND (i.quantity<>(SELECT count(*) FROM serial_numbers s WHERE s.variant_id=i.variant_id AND s.warehouse_id=i.warehouse_id AND s.status IN ('AVAILABLE','RESERVED')) OR i.reserved_quantity<>(SELECT count(*) FROM serial_numbers s WHERE s.variant_id=i.variant_id AND s.warehouse_id=i.warehouse_id AND s.status='RESERVED'));
SELECT 'duplicate_customer_phone_groups',count(*) FROM (SELECT coalesce(c.phone,u.phone) phone FROM customers c LEFT JOIN users u USING(user_id) WHERE coalesce(c.phone,u.phone) IS NOT NULL GROUP BY 1 HAVING count(*)>1) t;
SELECT 'knowledge_documents',status,count(*) FROM knowledge_documents GROUP BY status;
SELECT 'knowledge_chunks',count(*),count(embedding_vector) FROM knowledge_chunks;
SELECT 'unused_qna_rows',count(*) FROM chatbot_qna;
SELECT 'unused_script_rows',count(*) FROM chatbot_scripts;
COMMIT;
